import { useState } from "react";

export function ExpandedState({
  summaryText = "{{summaryText}}",
  body = "{{body}}",
  accent = "{{accent}}",
  force = {{force}},
}) {
  const [open, setOpen] = useState(force);
  return (
    <div>
      <details open={open} onToggle={(e) => setOpen(e.target.open)}
        style={{ width: 300, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", border: "1.5px solid #24143025", borderRadius: 10, padding: "4px 16px" }}>
        <summary style={{ listStyle: "none", cursor: "pointer", padding: "13px 0", fontWeight: 700, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          {summaryText}
          <span aria-hidden="true" style={{ color: accent, display: "inline-block", transform: open ? "rotate(90deg)" : "none" }}>▸</span>
        </summary>
        <p style={{ margin: "0 0 14px", fontSize: 13, color: "#241430cc" }}>{body}</p>
      </details>
      <p style={{ width: 300, margin: "8px 0 0", fontSize: 11, color: "#241430888" }}>Open is the real expanded state, matched with the real <code>open</code> attribute — click the summary to close it, or pass <code>force</code> false.</p>
    </div>
  );
}
